import { encodeSudoku } from '@sudoku/sencode';
import {
	gameModel,
	grid as puzzleGridStore,
	invalidCells as invalidCellsStore,
	userGrid as userGridStore,
} from './game';

export const grid = {
	subscribe: puzzleGridStore.subscribe,

	get(gridStore, x, y) {
		return gridStore[y][x];
	},

	getSencode(gridStore) {
		return encodeSudoku(gridStore);
	},
};

export const userGrid = {
	subscribe: userGridStore.subscribe,

	set(pos, value) {
		gameModel.guess(pos, value);
	},

	applyHint(pos) {
		gameModel.hint(pos);
	},
};

export const invalidCells = invalidCellsStore;
